<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
 import type{DesignSnapshot,DesignOperation,OpeningElement}from'@schubert/contracts';
 import MeasurementField from'./MeasurementField.svelte';
 let{snapshot,opening,documents=[],actorId='',canConfirm=false,disabled=false,onchange}:{snapshot:DesignSnapshot;opening:OpeningElement;documents?:any[];actorId?:string;canConfirm?:boolean;disabled?:boolean;onchange:(ops:DesignOperation[])=>void}=$props();
 const fields=[['offsetAlongWallMeasureId','Abstand längs der Wand'],['widthMeasureId','Lichte Breite'],['heightMeasureId','Lichte Höhe'],['sillHeightMeasureId','Brüstung / Schwelle']]as const;
</script>
<div class="opening"><h3>Öffnung in der Wand</h3><label>Bezugswand<select use:searchableSelect={opening.wallId} value={opening.wallId} onchange={event=>onchange([{type:'set_opening',elementId:opening.id,wallId:event.currentTarget.value}])} {disabled}>{#each snapshot.elements.filter(e=>e.kind==='wall') as wall}<option value={wall.id}>{wall.label}</option>{/each}</select></label>
 <label>Öffnungstyp<select use:searchableSelect={opening.openingType} value={opening.openingType} onchange={event=>onchange([{type:'set_opening',elementId:opening.id,openingType:event.currentTarget.value as OpeningElement['openingType']}])} {disabled}><option value="door">Tür</option><option value="window">Fenster</option><option value="passage">Durchgang</option><option value="recess">Nische</option></select></label>
 {#each fields as [field,label]}<MeasurementField {snapshot} measureId={opening[field]} {label} elementId={opening.id} {field} {actorId} {canConfirm} evidence={documents} {disabled} onchange={onchange}/>{/each}
 {#if opening.openingType==='recess'}<MeasurementField {snapshot} measureId={opening.recessDepthMeasureId??null} label="Nischentiefe ab Kernoberfläche" elementId={opening.id} field="recessDepthMeasureId" {actorId} {canConfirm} evidence={documents} {disabled} onchange={onchange}/><label>Seite des Wandkerns<select use:searchableSelect={opening.recessSide??'left'} value={opening.recessSide??'left'} onchange={event=>onchange([{type:'set_opening',elementId:opening.id,recessSide:event.currentTarget.value as 'left'|'right'}])} {disabled}><option value="left">Links in Wandrichtung</option><option value="right">Rechts in Wandrichtung</option></select></label><p>Die Tiefe beginnt an der Kernoberfläche. Zugeordnete Schichten auf dieser Seite werden ausgespart; der verbleibende Wandkern bleibt tatsächlich erhalten.</p>
 {:else if opening.openingType==='door'}<label>Öffnungsrichtung<select use:searchableSelect={opening.openingDirection} value={opening.openingDirection} onchange={event=>onchange([{type:'set_opening',elementId:opening.id,openingDirection:event.currentTarget.value as OpeningElement['openingDirection']}])} {disabled}><option value="inward">Nach innen / links der Wandrichtung</option><option value="outward">Nach außen / rechts der Wandrichtung</option><option value="sliding">Schiebend</option><option value="none">Keine</option></select></label><label>Bandseite<select use:searchableSelect={opening.hingeSide??''} value={opening.hingeSide??''} onchange={event=>onchange([{type:'set_opening',elementId:opening.id,hingeSide:event.currentTarget.value as 'left'|'right'}])} {disabled}><option value="" disabled>Noch offen</option><option value="left">Links</option><option value="right">Rechts</option></select></label><p>Innen und außen sind über die gerichtete Wand definiert; die tatsächliche Raumnutzung fachlich prüfen.</p>{/if}
</div>
<style>.opening{font-size:13px;line-height:1.65}.opening h3{font-size:14px;font-weight:600}.opening p{font-size:12px;color:var(--muted)}.opening label{display:block;margin:16px 0;font-size:13px}.opening select{display:block;box-sizing:border-box;width:100%;font:inherit;font-size:14px;padding:10px;border:1px solid var(--line);border-radius:4px;background:var(--paper);color:var(--ink);min-height:44px;margin-top:7px}@media(max-width:720px){.opening select{font-size:16px;min-height:48px}}</style>
